import { Injectable } from '@nestjs/common';
import { AdminRole } from '@prisma/client';
import { PrismaService } from '@shared/infrastructure/prisma/prisma.service';
import { GeneratedReport } from '../../domain/generated-report.entity';
import {
  GeneratedReportRepository,
  ReportActivityRow,
} from '../../domain/generated-report.repository';
import { ReportFormat, ReportType } from '../../domain/report-kind';

/** The role label shown in the activity feed ("Generated by Operations Manager"). */
const ROLE_LABEL: Record<AdminRole, string> = {
  SUPER_ADMIN: 'Admin',
  OPERATIONS_MANAGER: 'Operations Manager',
  COORDINATOR: 'Coordinator',
};

/** Prisma adapter for the report activity feed. */
@Injectable()
export class GeneratedReportPrismaRepository implements GeneratedReportRepository {
  constructor(private readonly prisma: PrismaService) {}

  async save(report: GeneratedReport): Promise<void> {
    await this.prisma.generatedReport.create({
      data: {
        id: report.id,
        type: report.type,
        title: report.title,
        format: report.format,
        currency: report.currency,
        periodStart: report.periodStart,
        periodEnd: report.periodEnd,
        generatedById: report.generatedById,
        createdAt: report.createdAt,
      },
    });
  }

  async listRecent(limit: number): Promise<ReportActivityRow[]> {
    const rows = await this.prisma.generatedReport.findMany({
      orderBy: { createdAt: 'desc' },
      take: limit,
      select: {
        id: true,
        type: true,
        title: true,
        format: true,
        createdAt: true,
        generatedBy: { select: { role: true } },
      },
    });
    return rows.map((row) => ({
      id: row.id,
      type: row.type as ReportType,
      title: row.title,
      format: row.format as ReportFormat,
      generatedAt: row.createdAt,
      generatedByLabel: row.generatedBy === null ? null : ROLE_LABEL[row.generatedBy.role],
    }));
  }
}
